widget.solution:
import math

def bet_size_from_prob(p):
    # AFML: z = (p - 1/2) / sqrt(p(1 - p)), size = 2 * Phi(z) - 1
    z = (p - 0.5) / math.sqrt(p * (1 - p))
    return math.erf(z / math.sqrt(2))

def kelly_fraction(p, b):
    # win b per 1 staked with chance p, lose the stake otherwise
    return p - (1 - p) / b

def fractional_kelly(p, b, frac):
    # frac times Kelly, and 0 when Kelly is negative
    return max(0.0, frac * kelly_fraction(p, b))

