def discretise(size, step):
    return round(size / step) * step

def average_active_bets(sizes, starts, ends, n_days):
    positions = []
    for t in range(n_days):
        open_sizes = [m for m, a, b in zip(sizes, starts, ends) if a <= t <= b]   # sizes of the bets with start <= t <= end
        positions.append(sum(open_sizes) / len(open_sizes) if open_sizes else 0.0)
    return positions
